def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find the largest 4-connected component of color 1: this is the motif.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == 1 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append(comp)
    motif = max(components, key=len)
    r0, r1 = min(r for r, _ in motif), max(r for r, _ in motif)
    c0, c1 = min(c for _, c in motif), max(c for _, c in motif)
    mh, mw = r1-r0+1, c1-c0+1
    mask = {(r-r0, c-c0) for r, c in motif}

    # The color key is a rectangular repeated stripe: each row is the same
    # horizontal palette, or (for the transposed presentation) each column.
    keys = []
    for y in range(h):
        for x in range(w):
            for n in range(2, min(h-y, w-x)+1):
                if all(g[yy][xx] != 0 for yy in range(y,y+n) for xx in range(x,x+n)):
                    pass
    # Detect maximal runs of identical nonzero row-vectors; palette entries
    # are the distinct consecutive colors in the repeated vector.
    for y in range(h):
        row = g[y]
        for x in range(w):
            for end in range(x+2, w+1):
                seq = row[x:end]
                if 0 in seq or len(set(seq)) != len(seq):
                    break
                length = 1
                while y+length < h and g[y+length][x:end] == seq:
                    length += 1
                if length >= 2:
                    keys.append((length*(end-x), y, x, length, end-x, seq))
    if not keys:
        # Transposed key: identical column-vectors.
        for x in range(w):
            for y in range(h):
                for end in range(y+2, h+1):
                    seq = [g[yy][x] for yy in range(y,end)]
                    if 0 in seq or len(set(seq)) != len(seq):
                        break
                    length = 1
                    while x+length < w and [g[yy][x+length] for yy in range(y,end)] == seq:
                        length += 1
                    if length >= 2:
                        keys.append((length*(end-y), y, x, end-y, length, seq))
    if not keys:
        return g
    _, ky, kx, kh, kw, palette = max(keys)
    if len(palette) < 2 or 1 not in palette:
        return g

    # Stack one motif copy per key color, anchored so the existing color-1
    # copy occupies its palette position.
    top = r0 - palette.index(1) * mh
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        y0 = top + i * mh
        for dy, dx in mask:
            yy, xx = y0 + dy, c0 + dx
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = color
    return out


